import axios from 'axios';
import * as cheerio from 'cheerio';

export async function handler(event, context) {
  const { query, sort, page } = event.queryStringParameters;

  if (!query) {
    return {
      statusCode: 400,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ error: 'Missing "query" parameter. Provide a search term or tag (e.g., anime, teen, etc.)' }),
    };
  }

  try {
    // Build URL based on sort type
    const sortType = sort || 'recent';
    const pageNum = parseInt(page) || 1;

    let searchUrl;
    if (sortType === 'recent') {
      searchUrl = `https://www.eporner.com/tag/${query}/${pageNum > 1 ? pageNum + '/' : ''}`;
    } else {
      searchUrl = `https://www.eporner.com/tag/${query}/${sortType}/${pageNum > 1 ? pageNum + '/' : ''}`;
    }

    // Fetch search results
    const response = await axios.get(searchUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept-Encoding': 'gzip, deflate, br',
        'Referer': 'https://www.eporner.com/',
        'Cache-Control': 'max-age=0',
        'Sec-Ch-Ua': '"Google Chrome";v="143", "Chromium";v="143", "Not A(Brand";v="24"',
        'Sec-Ch-Ua-Mobile': '?0',
        'Sec-Ch-Ua-Platform': '"Windows"',
        'Sec-Fetch-Dest': 'document',
        'Sec-Fetch-Mode': 'navigate',
        'Sec-Fetch-Site': 'same-origin',
        'Sec-Fetch-User': '?1',
        'Upgrade-Insecure-Requests': '1',
      },
      timeout: 15000,
      maxRedirects: 5,
    });

    if (response.status !== 200) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    const $ = cheerio.load(response.data);
    const videos = [];

    // Try multiple selectors for video items
    const videoSelectors = ['.mb', 'div[data-id]', '.mbimg', '.video-item'];
    let $videoItems = $();

    for (const selector of videoSelectors) {
      $videoItems = $(selector);
      if ($videoItems.length > 0) break;
    }

    $videoItems.each((i, el) => {
      const $el = $(el);

      // Extract video ID
      const videoId = $el.attr('data-id') || $el.attr('id')?.replace(/\D/g, '');

      // Extract URL
      let url = null;
      const link = $el.find('a[href*="/video-"], a[href*="/hd-porn/"]').first().attr('href');
      if (link) {
        url = link.startsWith('http') ? link : `https://www.eporner.com${link}`;
      }

      // Extract title
      const title = $el.find('.mbtit a, a[title]').first().text().trim() || 
                    $el.find('a[title]').attr('title') || 
                    'Unknown Title';

      // Extract thumbnail
      const thumbnail = $el.find('img').attr('src') || 
                       $el.find('img').attr('data-src') || 
                       $el.find('img').attr('data-original') || 
                       null;

      // Extract duration
      const duration = $el.find('.mbtim, .duration, [class*="time"]').first().text().trim() || null;

      // Extract quality
      const quality = $el.find('.mvhdico span, .quality, [class*="quality"]').first().text().trim() || null;

      // Extract rating
      const rating = $el.find('.mbrate, .rating, [class*="rate"]').first().text().trim() || null;

      // Extract views
      const views = $el.find('.mbvie, .views, [class*="view"]').first().text().trim() || null;

      // Extract uploader
      const uploader = $el.find('.mb-uploader a, [class*="uploader"] a').first().text().trim() || null;

      if (url) {
        videos.push({
          id: videoId || null,
          title,
          url,
          thumbnail,
          duration,
          quality,
          rating,
          views,
          uploader,
        });
      }
    });

    // Extract pagination info
    let totalPages = 1;
    let hasNextPage = false;

    $('.pagingnav a, .pagination a').each((i, el) => {
      const text = $(el).text().trim();
      if (!isNaN(text)) {
        const num = parseInt(text);
        if (num > totalPages) totalPages = num;
      }
      if (text.toLowerCase().includes('next')) {
        hasNextPage = true;
      }
    });

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        success: true,
        data: {
          owner: "@THENUX",
          query,
          sort: sortType,
          page: pageNum,
          totalPages,
          hasNextPage,
          results: videos.length,
          videos,
        },
      }),
    };
  } catch (error) {
    console.error('Error:', error.message);
    return {
      statusCode: 500,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        error: `Failed to search: ${error.message}`,
        query,
      }),
    };
  }
}
